#!/usr/bin/env python3
"""MS7 answer-quality eval.

For every query in queries.json, generate an actual answer in four conditions
and save them for grading:

  model_only  - query alone (Claude's own knowledge, no CMF context)
  memory      - query + the recall_mem block, rendered as the MCP tool delivers it
  wiki        - query + the search_wiki block
  both        - query + the verbatim get_context output (runs.json.combined.text)

Answers are generated by `claude -p --restricted --strict-mcp-config` run from an
isolated scratch cwd, so the model_only arm is a true baseline: no MCP, no
CLAUDE.md, no saved memory. Reproducible; re-run after any retrieval change.

    .venv/bin/python tests/fixtures/ms7_eval/answer_eval.py \
        [--runs runs.json] [--out answers.json] [--model sonnet] \
        [--limit N] [--conditions model_only,memory,wiki,both]

Needs the `claude` CLI on PATH and a logged-in Claude Code session. Does NOT
touch the graph or wiki — it only reads the already-captured runs.json.
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tempfile
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
CONDITIONS = ("model_only", "memory", "wiki", "both")

_CTRL = {c: None for c in range(0x20) if c not in (0x09, 0x0A)}  # drop C0 ctrl except tab/newline


def _sanitize(s: str) -> str:
    """Strip NUL and other control chars — extracted PDF text sometimes carries
    them (e.g. the condo inspection PDF), and subprocess/argv rejects NUL."""
    return s.translate(_CTRL)

_ANSWER_SYS = (
    "You are answering a question for the user from your own knowledge plus any "
    "CONTEXT block provided below. Answer directly and concisely (2-5 sentences). "
    "Use only the question and the CONTEXT; do not speculate. If the answer is not "
    "available to you, say exactly: \"I don't have enough information to answer that.\""
)


def _render_memory(items: list[dict]) -> str:
    """Reproduce format_memory_results_for_mcp's shape from a runs.json memory block."""
    if not items:
        return "No matching episodic memory found."
    out = [f"### Episodic Memory Search Results", f"Retrieved {len(items)} fact(s):\n"]
    for i, it in enumerate(items, 1):
        inv = it.get("invalid_at")
        status = "ACTIVE" if not inv else f"SUPERSEDED (invalidated at {inv})"
        labels = [s["name"] for s in it.get("source_eps", [])] or it.get("episodes", [])
        out.append(f"#### {i}. {it.get('fact','')}")
        out.append(f"- **Status:** `{status}`")
        out.append(f"- **Valid From:** `{it.get('valid_at','N/A')}`")
        if labels:
            out.append(f"- **Source Episodes:** `{', '.join(map(str, labels))}`")
        for se in it.get("source_eps", []):
            if not se.get("content"):
                continue
            prov = f"  _({se['prov']})_" if se.get("prov") else ""
            out.append(f"  > {se['content']}{prov}")
        out.append("")
    return "\n".join(out).strip()


def _render_wiki(items: list[dict]) -> str:
    if not items:
        return "No matching durable knowledge found."
    out = [f"### Durable Knowledge Search Results ({len(items)} hit(s)):\n"]
    for i, it in enumerate(items, 1):
        out.append(f"#### {i}. `{it.get('path','')}` ({it.get('area','')})  — score {it.get('score')}")
        if it.get("snippet"):
            out.append(f"> {it['snippet']}")
        out.append("")
    return "\n".join(out).strip()


def _prompt(query: str, condition: str, rec: dict) -> str:
    if condition == "model_only":
        ctx = None
    elif condition == "memory":
        ctx = _render_memory(rec["memory"]["items"])
    elif condition == "wiki":
        ctx = _render_wiki(rec["knowledge"]["items"])
    elif condition == "both":
        ctx = rec["combined"]["text"]
    else:
        raise ValueError(condition)
    parts = [_ANSWER_SYS, "", f"QUESTION: {query}"]
    if ctx is not None:
        parts += ["", "CONTEXT:", ctx]
    parts += ["", "ANSWER:"]
    return _sanitize("\n".join(parts))


def _ask(prompt: str, model: str, cwd: str) -> str:
    # Drop the entrypoint inherited from a parent Desktop session, or these
    # runs' transcripts are stamped entrypoint=claude-desktop and pass for
    # real Code-tab sessions (docs/CLAUDE-HARNESS-PROVENANCE-PLAN.md).
    env = {k: v for k, v in os.environ.items() if k != "CLAUDE_CODE_ENTRYPOINT"}
    try:
        p = subprocess.run(
            ["claude", "-p", prompt, "--model", model, "--restricted", "--strict-mcp-config"],
            cwd=cwd, capture_output=True, text=True, timeout=180, env=env,
        )
    except Exception as e:  # subprocess spawn / timeout / decode
        return f"[[generator error: {e!r}]]"
    if p.returncode != 0:
        # The CLI prints some failures (e.g. an expired login) to stdout, not stderr.
        return f"[[generator error rc={p.returncode}: {(p.stderr.strip() or p.stdout.strip())[:200]}]]"
    return p.stdout.strip()


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--runs", default=str(HERE / "runs.json"))
    ap.add_argument("--out", default=str(HERE / "answers.json"))
    ap.add_argument("--model", default="sonnet")
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--conditions", default=",".join(CONDITIONS))
    ap.add_argument("--resume", action="store_true", help="keep existing answers.json, fill only missing pairs")
    args = ap.parse_args()

    conditions = [c.strip() for c in args.conditions.split(",") if c.strip()]
    queries = json.loads((HERE / "queries.json").read_text())["queries"]
    runs = {q["id"]: q for q in json.loads(Path(args.runs).read_text())["queries"]}
    if args.limit:
        queries = queries[: args.limit]

    out_path = Path(args.out)
    resume = args.resume and out_path.exists()
    records: list[dict] = []
    done_pairs: set[tuple] = set()
    if resume:
        prev = json.loads(out_path.read_text())
        records = [r for r in prev.get("answers", [])
                   if not str(r.get("answer", "")).startswith("[[generator error")]
        done_pairs = {(r["query_id"], r["condition"]) for r in records}
        print(f"resume: {len(done_pairs)} answers already captured, filling the rest")
    elif out_path.exists():
        bak = out_path.with_suffix(f".prev{out_path.suffix}")
        i = 1
        while bak.exists():
            bak = out_path.with_suffix(f".prev{i}{out_path.suffix}")
            i += 1
        out_path.rename(bak)
        print(f"backed up existing → {bak.name}")

    def _flush():
        out_path.write_text(json.dumps({
            "generated": time.strftime("%Y-%m-%dT%H:%M:%S%z"), "model": args.model,
            "runs_source": str(Path(args.runs).name), "conditions": conditions,
            "answers": records,
        }, indent=1, ensure_ascii=False))
    with tempfile.TemporaryDirectory(prefix="ms7-answer-eval-") as cwd:
        total = len(queries) * len(conditions)
        n = 0
        for q in queries:
            rec = runs[q["id"]]
            for cond in conditions:
                n += 1
                if (q["id"], cond) in done_pairs:
                    print(f"[{n:3d}/{total}] {q['id']:4s} {cond:10s}  (cached)", flush=True)
                    continue
                prompt = _prompt(q["query"], cond, rec)
                t0 = time.perf_counter()
                ans = _ask(prompt, args.model, cwd)
                dt = round(time.perf_counter() - t0, 1)
                print(f"[{n:3d}/{total}] {q['id']:4s} {cond:10s} {dt:5.1f}s  {ans[:70]!r}", flush=True)
                records.append({
                    "query_id": q["id"], "group": q["group"], "condition": cond,
                    "query": q["query"], "gold_needs": q["gold_needs"],
                    "prompt_chars": len(prompt), "latency_s": dt, "answer": ans,
                })
                _flush()

    _flush()
    print(f"\nwrote {out_path}  ({len(records)} answers)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
